    // ─────────── فصل ۱: موش‌های اوران ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Rats of Oran", titlePersian = "موش‌های اوران",
        paragraphs = listOf(
            StoryParagraph("The unusual events described in this chronicle occurred in 194— in Oran, a city on the Algerian coast.", "رویدادهای غیرعادی توصیف‌شده در این تاریخ‌نگاری در سال ۱۹۴— در اوران، شهری در ساحل الجزایر، رخ دادند."),
            StoryParagraph("Oran is a dull city, a commercial city, a city that has turned its back on the sea.", "اوران شهری کسل‌کننده است، شهری تجاری، شهری که پشتش را به دریا کرده."),
            StoryParagraph("The people of Oran work hard, make money, fall in love, and die, all in the same ordinary way.", "مردم اوران سخت کار می‌کنند، پول درمی‌آورند، عاشق می‌شوند و می‌میرند، همه به همان شیوه معمولی."),
            StoryParagraph("They do not think about death, or about the meaning of life, or about anything that cannot be counted or bought.", "به مرگ فکر نمی‌کنند، نه به معنای زندگی، نه به هیچ چیز که نمی‌شود شمرد یا خرید."),
            StoryParagraph("Dr. Bernard Rieux was one of the doctors in the city, and he was no different from the others, except that he worked harder and thought more.", "دکتر برنارد ریو یکی از پزشکان شهر بود و با دیگران تفاوتی نداشت، جز اینکه سخت‌تر کار می‌کرد و بیشتر فکر می‌کرد."),
            StoryParagraph("His wife was ill, and she had been sent to a sanatorium in the mountains, and he missed her deeply.", "همسرش مریض بود و به آسایشگاهی در کوه‌ها فرستاده شده بود و عمیقاً دلتنگش بود."),
            StoryParagraph("One morning, as he was leaving his apartment, he found a dead rat on the landing.", "یک صبح، هنگامی که از آپارتمانش بیرون می‌رفت، موش مرده‌ای روی پاگرد پله‌ها یافت."),
            StoryParagraph("He thought it was strange, but he did not think about it for long; a dead rat was nothing to worry about.", "فکر کرد عجیب است اما زیاد به آن فکر نکرد؛ موش مرده چیزی برای نگرانی نبود."),
            StoryParagraph("But the next day, there was another dead rat, and then another, and then more.", "اما روز بعد، موش مرده دیگری بود و بعد یکی دیگر و بعد بیشتر."),
            StoryParagraph("The concierge of his building, an old man named Michel, complained about the rats.", "سرایدار ساختمانش، پیرمردی به نام میشل، از موش‌ها شکایت کرد."),
            StoryParagraph("'I have never seen anything like it,' Michel said. 'There are rats everywhere.'", "میشل گفت: «هرگز چیزی مثل این ندیده‌ام. همه‌جا موش است.»"),
            StoryParagraph("Soon, the dead rats were being found in the streets, in the alleyways, in the courtyards.", "به‌زودی، موش‌های مرده در خیابان‌ها، در کوچه‌ها، در حیاط‌ها پیدا می‌شدند."),
            StoryParagraph("The garbage collectors found hundreds of them every day.", "زباله‌جمع‌کنان هر روز صدها تا از آنها را پیدا می‌کردند."),
            StoryParagraph("The city authorities ordered the rats to be collected and burned.", "مقامات شهر دستور دادند موش‌ها جمع‌آوری و سوزانده شوند."),
            StoryParagraph("But the rats kept coming; they seemed to be migrating from somewhere, from some hidden source.", "اما موش‌ها مدام می‌آمدند؛ به نظر می‌رسید از جایی مهاجرت می‌کنند، از سرچشمه‌ای پنهان."),
            StoryParagraph("Then, one day, Michel the concierge became ill.", "بعد، یک روز، میشل سرایدار مریض شد."),
            StoryParagraph("He had a high fever and swollen glands in his neck, and he could not get out of bed.", "تب بالا و غدد متورم در گردنش داشت و نمی‌توانست از تخت بلند شود."),
            StoryParagraph("Dr. Rieux was called, and he examined Michel, and he was alarmed by what he found.", "دکتر ریو را خبر کردند و میشل را معاینه کرد و از آنچه یافت هشدار شد."),
            StoryParagraph("He called another doctor, a colleague named Castel, and Castel examined Michel too.", "دکتر دیگری را خبر کرد، همکارش به نام کاستل و کاستل هم میشل را معاینه کرد."),
            StoryParagraph("'It looks like the plague,' Castel said, and his voice was grave.", "کاستل گفت: «مثل طاعون است.» و صدایش جدی بود."),
            StoryParagraph("'The plague?' Rieux said. 'That is impossible. The plague has not been seen in Europe for decades.'", "ریو گفت: «طاعون؟ غیرممکن است. طاعون دهه‌ها در اروپا دیده نشده.»"),
            StoryParagraph("'I know,' Castel said. 'But I cannot think of anything else it could be.'", "کاستل گفت: «می‌دانم. اما نمی‌توانم فکر کنم چیز دیگری باشد.»"),
            StoryParagraph("Michel died that night, and the death was a hard one; his body was covered with black swellings.", "میشل آن شب مرد و مرگ سختی بود؛ بدنش پوشیده از تومورهای سیاه بود."),
            StoryParagraph("Rieux called the city authorities and reported the case.", "ریو مقامات شهر را خبر کرد و مورد را گزارش داد."),
            StoryParagraph("At first, they did not want to believe him; the plague was a thing of the past, a thing of the Middle Ages.", "اول، نمی‌خواستند باورش کنند؛ طاعون چیزی از گذشته بود، چیزی از قرون وسطی."),
            StoryParagraph("'It cannot happen here,' they said. 'Not in the twentieth century.'", "گفتند: «اینجا نمی‌تواند اتفاق بیفتد. نه در قرن بیستم.»"),
            StoryParagraph("But more people became ill, and more people died, and the symptoms were always the same.", "اما افراد بیشتری مریض شدند و افراد بیشتری مردند و علائم همیشه یکسان بود."),
            StoryParagraph("The fever, the swellings, the black spots on the skin, the rapid death.", "تب، تومورها، لکه‌های سیاه روی پوست، مرگ سریع."),
            StoryParagraph("Rieux kept a careful record: ten cases on the first day, twenty on the second, forty on the third.", "ریو سابقه دقیقی نگه داشت: ده مورد در روز اول، بیست در روز دوم، چهل در روز سوم."),
            StoryParagraph("The numbers grew every day, and the city began to panic.", "اعداد هر روز رشد می‌کردند و شهر شروع به وحشت کرد."),
            StoryParagraph("People began to leave; they packed their bags and tried to escape.", "مردم شروع کردند به رفتن؛ چمدان‌هایشان را بستند و تلاش کردند فرار کنند."),
            StoryParagraph("But the authorities closed the city gates, and no one could enter or leave.", "اما مقامات دروازه‌های شهر را بستند و هیچ‌کس نمی‌توانست وارد یا خارج شود."),
            StoryParagraph("Oran was put under quarantine, and the people of Oran were prisoners.", "اوران تحت قرنطینه قرار گرفت و مردم اوران زندانی شدند."),
            StoryParagraph("'This is the beginning,' Rieux wrote in his notebook. 'This is the beginning of the plague.'", "ریو در دفترش نوشت: «این آغاز است. این آغاز طاعون است.»"),
            StoryParagraph("He did not know how long the plague would last, or how many would die, or whether he himself would survive.", "نمی‌دانست طاعون چقدر طول می‌کشد، یا چند نفر می‌میرند، یا آیا خودش زنده می‌ماند."),
            StoryParagraph("He only knew that his life had changed, and that the lives of everyone in Oran had changed, and that nothing would ever be the same.", "تنها می‌دانست زندگی‌اش تغییر کرده و زندگی همه در اوران تغییر کرده و هیچ چیز هرگز همان نخواهد بود."),
            StoryParagraph("The plague had come to Oran, and Oran would never forget it.", "طاعون به اوران آمده بود و اوران هرگز فراموشش نمی‌کرد."),
            StoryParagraph("And so began the chronicle of the plague, the record of the days of suffering, of courage, and of death.", "و اینگونه تاریخ‌نگاری طاعون آغاز شد، سابقه روزهای رنج، شجاعت و مرگ.")
        )
    )

    // ─────────── فصل ۲: قرنطینه ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "The Quarantine", titlePersian = "قرنطینه",
        paragraphs = listOf(
            StoryParagraph("The quarantine of Oran was announced on a hot afternoon in late spring.", "قرنطینه اوران در بعدازظهر گرمی از اواخر بهار اعلام شد."),
            StoryParagraph("The gates were closed, and the telegraph lines were cut off, and the ships were forbidden to dock.", "دروازه‌ها بسته شدند و خطوط تلگراف قطع شدند و کشتی‌ها از پهلو گرفتن منع شدند."),
            StoryParagraph("The people of Oran were separated from the world, isolated in their own city.", "مردم اوران از جهان جدا شدند، در شهر خودشان منزوی شدند."),
            StoryParagraph("At first, they did not understand what was happening; they believed that the quarantine would last only a few days.", "اول نفهمیدند چه اتفاقی می‌افتد؛ باور داشتند قرنطینه تنها چند روز طول می‌کشد."),
            StoryParagraph("But the days became weeks, and the weeks became months, and the quarantine continued.", "اما روزها به هفته‌ها تبدیل شدند و هفته‌ها به ماه‌ها و قرنطینه ادامه یافت."),
            StoryParagraph("Families were separated: those who had been outside the city could not return, and those inside could not leave.", "خانواده‌ها جدا شدند: کسانی که بیرون شهر بودند نمی‌توانستند برگردند و کسانی که داخل بودند نمی‌توانستند بروند."),
            StoryParagraph("Lovers, husbands and wives, parents and children — all were torn apart by the invisible wall of the quarantine.", "عاشقان، شوهر و زن، پدر و مادر و فرزندان — همه توسط دیوار نامرئی قرنطینه از هم پاره شدند."),
            StoryParagraph("Dr. Rieux worked day and night, visiting the sick, comforting the dying, recording the dead.", "دکتر ریو شبانه‌روز کار می‌کرد، به دیدن بیماران می‌رفت، در حال مرگ‌ها را دلداری می‌داد، مرده‌ها را ثبت می‌کرد."),
            StoryParagraph("He had no time to think about his own life, about his wife in the sanatorium, about his own exhaustion.", "وقتی نداشت به زندگی خودش فکر کند، به همسرش در آسایشگاه، به خستگی خودش."),
            StoryParagraph("His mother came to stay with him, to cook his meals, to make sure he ate, to make sure he slept.", "مادرش برای ماندن نزد او آمد، تا برایش غذا بپزد، مطمئن شود می‌خورد، مطمئن شود می‌خوابد."),
            StoryParagraph("'You must take care of yourself,' she said. 'You cannot save everyone.'", "گفت: «باید مراقب خودت باشی. نمی‌توانی همه را نجات دهی.»"),
            StoryParagraph("'I know,' he said. 'But I must try.'", "گفت: «می‌دانم. اما باید تلاش کنم.»"),
            StoryParagraph("A man named Jean Tarrou came to see him one day; Tarrou was a visitor to Oran, a man with no apparent occupation, a man who had been stranded by the quarantine.", "مردی به نام ژان تارو یک روز به دیدارش آمد؛ تارو بازدیدکننده‌ای در اوران بود، مردی بدون شغل ظاهری، مردی که توسط قرنطینه گیر افتاده بود."),
            StoryParagraph("'I want to help,' Tarrou said. 'I want to join your sanitary corps.'", "تارو گفت: «می‌خواهم کمک کنم. می‌خواهم به گروه بهداشتی‌تان بپیوندم.»"),
            StoryParagraph("'Why?' Rieux asked. 'This work is dangerous. You could die.'", "ریو پرسید: «چرا؟ این کار خطرناک است. ممکن است بمیری.»"),
            StoryParagraph("'I know,' Tarrou said. 'That is exactly why I want to do it.'", "تارو گفت: «می‌دانم. دقیقاً به همین دلیل می‌خواهم انجامش دهم.»"),
            StoryParagraph("Rieux accepted him, and Tarrou became his closest collaborator, and eventually his closest friend.", "ریو پذیرفتش و تارو نزدیک‌ترین همکارش شد و در نهایت نزدیک‌ترین دوستش."),
            StoryParagraph("Together, they organized volunteer groups, and together, they went from house to house, and together, they fought the plague.", "با هم گروه‌های داوطلب سازماندهی کردند و با هم از خانه‌ای به خانه رفتند و با هم با طاعون جنگیدند."),
            StoryParagraph("Another man, Raymond Rambert, was a journalist from Paris; he had come to Oran to write about the living conditions of the Arab workers.", "مرد دیگری، ریموند رامبرت، روزنامه‌نگاری از پاریس بود؛ به اوران آمده بود تا درباره شرایط زندگی کارگران عرب بنویسد."),
            StoryParagraph("Now he was trapped, separated from his wife, desperate to escape.", "حالا گیر افتاده بود، از همسرش جدا، ناامید برای فرار."),
            StoryParagraph("He tried every possible way to leave the city: bribery, smuggling, connections, anything.", "هر راه ممکن را برای ترک شهر امتحان کرد: رشوه، قاچاق، ارتباطات، هر چیزی."),
            StoryParagraph("But the quarantine was strict, and the guards were alert, and each attempt failed.", "اما قرنطینه سختگیرانه بود و نگهبانان هوشیار بودند و هر تلاش شکست می‌خورد."),
            StoryParagraph("One day, he came to Rieux and asked for help.", "یک روز، نزد ریو آمد و کمک خواست."),
            StoryParagraph("'You know the authorities,' Rambert said. 'You could get me a certificate of health. You could help me leave.'", "رامبرت گفت: «مقامات را می‌شناسی. می‌توانی گواهی سلامت برایم بگیری. می‌توانی کمکم کنی بروم.»"),
            StoryParagraph("'I could,' Rieux said. 'But I will not.'", "ریو گفت: «می‌توانم. اما نمی‌کنم.»"),
            StoryParagraph("'Why not?' Rambert cried. 'Do you not understand? My wife is in Paris. She is waiting for me. I love her.'", "رامبرت فریاد زد: «چرا نه؟ نمی‌فهمی؟ همسرم در پاریس است. منتظرم است. دوستش دارم.»"),
            StoryParagraph("'I understand,' Rieux said. 'But you are in Oran, and Oran is under quarantine, and you cannot leave.'", "ریو گفت: «می‌فهمم. اما تو در اورانی و اوران تحت قرنطینه است و نمی‌توانی بروی.»"),
            StoryParagraph("'That is not an answer,' Rambert said.", "رامبرت گفت: «این پاسخ نیست.»"),
            StoryParagraph("'It is the only answer,' Rieux said. 'I am sorry.'", "ریو گفت: «تنها پاسخ همین است. متأسفم.»"),
            StoryParagraph("Rambert left, angry and bitter, and he continued to try to escape.", "رامبرت رفت، عصبانی و تلخ و به تلاش برای فرار ادامه داد."),
            StoryParagraph("A priest named Father Paneloux gave a sermon at the cathedral, in which he declared that the plague was a punishment from God.", "کشیشی به نام پدر پانلو خطبه‌ای در کلیسای جامع خواند و در آن اعلام کرد که طاعون مجازاتی از جانب خداست."),
            StoryParagraph("'You have sinned,' he told the congregation, 'and God has sent this plague to punish you. You must repent. You must return to Him.'", "به جماعت گفت: «گناه کرده‌اید و خدا این طاعون را برای مجازاتتان فرستاده. باید توبه کنید. باید به او بازگردید.»"),
            StoryParagraph("Some of the people listened, and some did not; some believed, and some did not.", "برخی مردم گوش دادند و برخی نه؛ برخی باور کردند و برخی نه."),
            StoryParagraph("Rieux listened to the sermon, and he said nothing, for he had no words for such things.", "ریو به خطبه گوش داد و چیزی نگفت، چون برای چنین چیزهایی کلمه‌ای نداشت."),
            StoryParagraph("He did not believe in God, and he did not believe in punishment, and he did not believe that the plague had any meaning.", "به خدا باور نداشت و به مجازات باور نداشت و به اینکه طاعون معنایی داشته باشد باور نداشت."),
            StoryParagraph("The plague was simply there, a fact of nature, a thing that had to be fought, and he would fight it as long as he could.", "طاعون تنها آنجا بود، واقعیتی از طبیعت، چیزی که باید با آن جنگید و تا می‌توانست می‌جنگید."),
            StoryParagraph("The summer came, and the heat was unbearable, and the plague grew worse.", "تابستان آمد و گرما غیرقابل تحمل بود و طاعون بدتر شد."),
            StoryParagraph("The hospitals were full, and the cemeteries were full, and the crematoriums worked day and night.", "بیمارستان‌ها پر بودند و قبرستان‌ها پر و کوره‌های آدم‌سوزی شبانه‌روز کار می‌کردند."),
            StoryParagraph("The people of Oran learned to live with the plague, as one learns to live with anything, even the worst things.", "مردم اوران یاد گرفتند با طاعون زندگی کنند، همانطور که آدم یاد می‌گیرد با هر چیزی زندگی کند، حتی بدترین چیزها."),
            StoryParagraph("And yet, in the midst of all the suffering, there were moments of kindness, of courage, of love.", "و با این حال، در میان همه رنج، لحظاتی از مهربانی بود، از شجاعت، از عشق."),
            StoryParagraph("Rieux and Tarrou worked side by side, day after day, and their friendship grew deeper.", "ریو و تارو روز پس از روز کنار هم کار کردند و دوستی‌شان عمیق‌تر شد."),
            StoryParagraph("Rambert, after many months of trying to escape, finally decided to stay and help.", "رامبرت، پس از ماه‌ها تلاش برای فرار، سرانجام تصمیم گرفت بماند و کمک کند."),
            StoryParagraph("'I could be happy with my wife,' he said. 'But I would be ashamed. And shame is worse than the plague.'", "گفت: «می‌توانستم با همسرم خوشحال باشم. اما شرمنده می‌شدم. و شرم از طاعون بدتر است.»"),
            StoryParagraph("And so the months passed, and the plague continued, and the people of Oran waited for it to end.", "و اینگونه ماه‌ها گذشتند و طاعون ادامه یافت و مردم اوران منتظر پایانش ماندند.")
        )
    )

    // ─────────── فصل ۳: رنج ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "The Suffering", titlePersian = "رنج",
        paragraphs = listOf(
            StoryParagraph("The plague lasted through the summer, and into the autumn, and beyond.", "طاعون تا تابستان ادامه یافت و به پاییز و فراتر از آن."),
            StoryParagraph("The heat was unbearable, and the stench of death filled the streets, and the people of Oran learned to live with horror.", "گرما غیرقابل تحمل بود و بوی گند مرگ خیابان‌ها را پر کرده بود و مردم اوران یاد گرفتند با وحشت زندگی کنند."),
            StoryParagraph("The hospitals were so overcrowded that the sick were being kept in schools, in gymnasiums, in any building large enough.", "بیمارستان‌ها چنان پر بودند که بیماران را در مدارس نگه می‌داشتند، در سالن‌های ورزشی، در هر ساختمانی به اندازه کافی بزرگ."),
            StoryParagraph("The doctors and nurses worked until they collapsed, and then they got up and worked again.", "دکترها و پرستاران کار می‌کردند تا فرو بریزند و بعد بلند می‌شدند و دوباره کار می‌کردند."),
            StoryParagraph("Rieux rarely slept more than two or three hours at a time; he was thin and pale, and his eyes were hollow.", "ریو به‌ندرت بیش از دو یا سه ساعت در یک زمان می‌خوابید؛ لاغر و رنگ‌پریده بود و چشمانش گود افتاده."),
            StoryParagraph("Tarrou worked beside him, tireless, organized, always calm; he was the perfect comrade in a time of crisis.", "تارو کنارش کار می‌کرد، بی‌خستگی، سازمان‌یافته، همیشه آرام؛ در زمان بحران رفیق کاملی بود."),
            StoryParagraph("One day, they visited the stadium that had been turned into a quarantine camp.", "یک روز، به ورزشگاهی رفتند که به اردوگاه قرنطینه تبدیل شده بود."),
            StoryParagraph("Thousands of people were being held there, people who had been in contact with the sick, people who might be carrying the plague.", "هزاران نفر آنجا نگه داشته می‌شدند، کسانی که با بیماران در تماس بودند، کسانی که ممکن بود طاعون داشته باشند."),
            StoryParagraph("They were separated from their families, held in tents, fed on rationed food, waiting to see if they would live or die.", "از خانواده‌هایشان جدا بودند، در چادرها نگه داشته می‌شدند، با غذای جیره‌بندی‌شده تغذیه می‌شدند، منتظر بودند ببینند زنده می‌مانند یا می‌میرند."),
            StoryParagraph("Rieux walked among them, and he felt their despair, and he could do nothing to help them.", "ریو میانشان قدم زد و ناامیدی‌شان را حس کرد و نمی‌توانست کاری برای کمکشان بکند."),
            StoryParagraph("'This is the worst part,' Tarrou said. 'Worse than the deaths, worse than the plague itself.'", "تارو گفت: «این بدترین بخش است. بدتر از مرگ‌ها، بدتر از خود طاعون.»"),
            StoryParagraph("'Yes,' Rieux said. 'Because this is where hope dies.'", "ریو گفت: «بله. چون اینجا جایی است که امید می‌میرد.»"),
            StoryParagraph("That night, Rieux received a telegram from the sanatorium where his wife was staying.", "آن شب، ریو تلگرامی از آسایشگاهی که همسرش در آن بود دریافت کرد."),
            StoryParagraph("It said that her condition had worsened, and that she might not live much longer.", "می‌گفت حالش بدتر شده و ممکن است زیاد زنده نماند."),
            StoryParagraph("Rieux read the telegram, and he folded it, and he put it in his pocket, and he went back to work.", "ریو تلگرام را خواند و تا کرد و در جیبش گذاشت و به کار بازگشت."),
            StoryParagraph("There was nothing he could do; he could not leave Oran, he could not go to her, he could not save her.", "کاری نمی‌توانست بکند؛ نمی‌توانست اوران را ترک کند، نمی‌توانست به نزدش برود، نمی‌توانست نجاتش دهد."),
            StoryParagraph("He only hoped that she would not die alone, that someone would hold her hand at the end.", "تنها امیدوار بود تنها نمیرد، کسی در پایان دستش را بگیرد."),
            StoryParagraph("A few days later, Father Paneloux came to the hospital to see the suffering for himself.", "چند روز بعد، پدر پانلو برای دیدن خودِ رنج به بیمارستان آمد."),
            StoryParagraph("He saw a child dying of the plague, a young boy, ten years old, screaming in agony.", "کودکی را دید که از طاعون می‌مرد، پسر جوانی، ده ساله، در عذاب فریاد می‌زد."),
            StoryParagraph("He saw the doctors trying everything, and failing; he saw the parents weeping, and helpless; he saw the child finally die.", "دکترها را دید که همه چیز را امتحان می‌کردند و شکست می‌خوردند؛ پدر و مادر را دید که گریه می‌کردند و درمانده؛ کودک را دید که سرانجام مرد."),
            StoryParagraph("Father Paneloux left the hospital shaken, and he did not speak for many hours.", "پدر پانلو لرزان از بیمارستان بیرون رفت و ساعت‌ها صحبت نکرد."),
            StoryParagraph("When he finally spoke, he said, 'I do not understand. I do not understand why God would allow such a thing.'", "وقتی سرانجام صحبت کرد، گفت: «نمی‌فهمم. نمی‌فهمم چرا خدا چنین چیزی را اجازه می‌دهد.»"),
            StoryParagraph("Rieux said, 'Perhaps there is no God. Perhaps there is only the plague.'", "ریو گفت: «شاید خدایی نیست. شاید تنها طاعون هست.»"),
            StoryParagraph("Father Paneloux looked at him, and for a long time he said nothing.", "پدر پانلو نگاهش کرد و مدت طولانی چیزی نگفت."),
            StoryParagraph("'Then we must love what we cannot understand,' he said, at last. 'We must love God even when He does not love us.'", "سرانجام گفت: «پس باید آنچه نمی‌فهمیم را دوست بداریم. باید خدا را دوست بداریم حتی وقتی او ما را دوست ندارد.»"),
            StoryParagraph("Rieux did not answer; he had no answer for such faith.", "ریو پاسخ نداد؛ پاسخی برای چنین ایمانی نداشت."),
            StoryParagraph("That night, Father Paneloux fell ill, and within a few days, he was dead.", "آن شب، پدر پانلو مریض شد و در چند روز، مرده بود."),
            StoryParagraph("He refused to be moved to a hospital; he refused to be separated from his congregation; he died in his own bed, in his own rooms.", "از انتقال به بیمارستان امتناع کرد؛ از جدا شدن از جماعتش امتناع کرد؛ در تخت خودش، در اتاق‌های خودش مرد."),
            StoryParagraph("His death shocked the city, for even the priests were not spared.", "مرگش شهر را تکان داد، زیرا حتی کشیشان هم بخشیده نمی‌شدند."),
            StoryParagraph("The plague, they realized, did not care about virtue or vice, about faith or doubt; it killed everyone equally.", "دریافتند طاعون اهمیتی نمی‌دهد به فضیلت یا رذیلت، به ایمان یا شک؛ همه را به یکسان می‌کشد."),
            StoryParagraph("Tarrou, who had been watching all this with his usual calm, grew more thoughtful, more silent.", "تارو که همه این را با آرامش همیشگی‌اش تماشا می‌کرد، متفکرتر شد، ساکت‌تر."),
            StoryParagraph("One evening, he told Rieux about his past, about his father, about the man he had once been.", "یک عصر، به ریو از گذشته‌اش گفت، از پدرش، از مردی که زمانی بوده."),
            StoryParagraph("'My father was a prosecutor,' Tarrou said. 'He sent men to their deaths, calmly, professionally, as if it were nothing.'", "تارو گفت: «پدرم دادستان بود. مردان را به مرگ می‌فرستاد، با آرامش، با حرفه‌ایگری، گویی هیچ است.»"),
            StoryParagraph("'And I hated him for it; I hated the whole system that made such things possible.'", "«و به همین دلیل از او متنفر بودم؛ از تمام نظامی که چنین چیزها را ممکن می‌کرد متنفر بودم.»"),
            StoryParagraph("'So I became a revolutionary; I fought against everything, against the system, against the world.'", "«پس انقلابی شدم؛ علیه همه چیز جنگیدم، علیه نظام، علیه جهان.»"),
            StoryParagraph("'But in the end, I realized that I too was sending men to their deaths; I too was killing, in the name of justice.'", "«اما در نهایت فهمیدم من هم مردان را به مرگ می‌فرستم؛ من هم می‌کشتم، به نام عدالت.»"),
            StoryParagraph("'And so I decided to stop killing, and to help instead; I decided to fight against death, not to cause it.'", "«و اینگونه تصمیم گرفتم از کشتن دست بکشم و به جای آن کمک کنم؛ تصمیم گرفتم علیه مرگ بجنگم، نه اینکه باعثش شوم.»"),
            StoryParagraph("'That is why I am here, in Oran, in the plague, in the suffering; because this is where I can do good.'", "«به همین دلیل اینجا هستم، در اوران، در طاعون، در رنج؛ چون اینجا جایی است که می‌توانم خوبی کنم.»"),
            StoryParagraph("Rieux listened, and he understood, and he felt closer to Tarrou than he had ever felt to anyone.", "ریو گوش داد و فهمید و به تارو نزدیک‌تر از هر کس دیگری در تمام عمرش حس کرد."),
            StoryParagraph("'We are the same,' Rieux said. 'We both fight against death, without hope, without faith, without illusions.'", "ریو گفت: «ما یکی هستیم. هر دو با مرگ می‌جنگیم، بدون امید، بدون ایمان، بدون توهم.»"),
            StoryParagraph("'Yes,' Tarrou said. 'That is all we can do.'", "تارو گفت: «بله. این تنها کاری است که می‌توانیم بکنیم.»"),
            StoryParagraph("And so they continued to work, together, day after day, in the heart of the plague.", "و اینگونه به کار ادامه دادند، با هم، روز پس از روز، در قلب طاعون."),
            StoryParagraph("The winter came, and the plague began to slow, but it did not stop.", "زمستان آمد و طاعون شروع به کند شدن کرد اما متوقف نشد."),
            StoryParagraph("And the people of Oran, exhausted, demoralized, waited for the end that seemed never to come.", "و مردم اوران، فرسوده، روحیه‌باخته، منتظر پایانی ماندند که به نظر می‌رسید هرگز نمی‌آید.")
        )
    )

    // ─────────── فصل ۴: نقطه عطف ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "The Turning Point", titlePersian = "نقطه عطف",
        paragraphs = listOf(
            StoryParagraph("Months passed, and the plague continued, and the people of Oran learned to live with it.", "ماه‌ها گذشت و طاعون ادامه یافت و مردم اوران یاد گرفتند با آن زندگی کنند."),
            StoryParagraph("They no longer panicked; they no longer mourned; they no longer hoped.", "دیگر وحشت نمی‌کردند؛ دیگر عزاداری نمی‌کردند؛ دیگر امید نداشتند."),
            StoryParagraph("They simply went about their lives, as much as they could, and they waited.", "تنها به زندگی‌شان ادامه می‌دادند، تا آنجا که می‌توانستند و منتظر می‌ماندند."),
            StoryParagraph("Then, one day, in the middle of winter, the numbers began to fall.", "و بعد، یک روز، در میانه زمستان، اعداد شروع کردند به کاهش."),
            StoryParagraph("Fewer people were getting sick; fewer people were dying.", "افراد کمتری مریض می‌شدند؛ افراد کمتری می‌مردند."),
            StoryParagraph("At first, no one noticed; the change was too small to see.", "اول، هیچ‌کس متوجه نشد؛ تغییر بیش از حد کوچک بود که دیده شود."),
            StoryParagraph("But week after week, the numbers continued to fall, and slowly, the people began to hope.", "اما هفته پس از هفته، اعداد به کاهش ادامه دادند و آرام‌آرام، مردم شروع کردند به امید داشتن."),
            StoryParagraph("The serum that had been sent from Paris was working; the vaccines were effective; the doctors had finally found something that helped.", "سرمی که از پاریس فرستاده شده بود کار می‌کرد؛ واکسن‌ها مؤثر بودند؛ دکترها بالاخره چیزی یافته بودند که کمک می‌کرد."),
            StoryParagraph("Rieux, exhausted, continued to work, but now with a new energy, a new purpose.", "ریو، فرسوده، به کار ادامه داد اما حالا با انرژی جدیدی، هدف جدیدی."),
            StoryParagraph("'We may have won,' he said to Tarrou one evening. 'We may have beaten the plague.'", "یک عصر به تارو گفت: «شاید برده‌ایم. شاید طاعون را شکست داده‌ایم.»"),
            StoryParagraph("'Perhaps,' Tarrou said, but his voice was quiet, and there was something in it that Rieux did not understand.", "تارو گفت: «شاید.» اما صدایش آرام بود و چیزی در آن بود که ریو نمی‌فهمید."),
            StoryParagraph("A few days later, Tarrou fell ill.", "چند روز بعد، تارو مریض شد."),
            StoryParagraph("He had a fever, and a cough, and the symptoms that everyone in Oran had come to know too well.", "تب داشت و سرفه و علائمی که همه در اوران آن‌قدر خوب شناخته بودند."),
            StoryParagraph("Rieux examined him, and he knew at once what it was.", "ریو معاینه‌اش کرد و فوراً دانست چیست."),
            StoryParagraph("'It is the plague,' Rieux said, and his voice was calm, but his hands were trembling.", "ریو گفت: «طاعون است.» و صدایش آرام بود اما دستانش می‌لرزید."),
            StoryParagraph("'I know,' Tarrou said. 'I have known for a few days.'", "تارو گفت: «می‌دانم. چند روز است می‌دانم.»"),
            StoryParagraph("'Why did you not tell me?' Rieux asked.", "ریو پرسید: «چرا نگفتی؟»"),
            StoryParagraph("'Because there is nothing you could do,' Tarrou said. 'And because I did not want to spend my last days talking about my death.'", "تارو گفت: «چون کاری نمی‌توانستی بکنی. و چون نمی‌خواستم روزهای آخرم را صرف صحبت درباره مرگم کنم.»"),
            StoryParagraph("Rieux fought for him; he tried every treatment, every remedy, every desperate measure.", "ریو برایش جنگید؛ هر درمانی را امتحان کرد، هر درمانی، هر اقدام درمانده‌ای."),
            StoryParagraph("He stayed by his side day and night, holding his hand, talking to him, willing him to live.", "شبانه‌روز کنارش ماند، دستش را گرفت، با او صحبت کرد، خواست زنده بماند."),
            StoryParagraph("But Tarrou grew weaker, and weaker, and finally, on a clear winter morning, he died.", "اما تارو ضعیف‌تر و ضعیف‌تر شد و سرانجام، در صبح روشنی از زمستان، مرد."),
            StoryParagraph("Rieux was with him at the end; he held his hand, and he watched the light leave his eyes.", "ریو در پایان با او بود؛ دستش را گرفت و تماشا کرد که نور از چشمانش می‌رفت."),
            StoryParagraph("He did not weep, not then; he had no tears left; he had seen too many deaths.", "گریه نکرد، نه آن وقت؛ اشکی برایش نمانده بود؛ مرگ‌های زیادی دیده بود."),
            StoryParagraph("But something in him died with Tarrou, something that could never be replaced.", "اما چیزی در او با تارو مرد، چیزی که هرگز نمی‌شد جایگزینش کرد."),
            StoryParagraph("He had lost his closest friend, his truest comrade, the only person who had understood him completely.", "نزدیک‌ترین دوستش را از دست داده بود، صادق‌ترین رفیقش، تنها کسی که کاملاً درکش کرده بود."),
            StoryParagraph("He went back to work, as he always did; there was nothing else to do.", "به کار بازگشت، همانطور که همیشه می‌کرد؛ کار دیگری نبود."),
            StoryParagraph("The plague continued to retreat, and the people of Oran began to prepare for its end.", "طاعون به عقب‌نشینی ادامه داد و مردم اوران شروع کردند به آماده شدن برای پایانش."),
            StoryParagraph("The gates would be opened; the ships would dock; the trains would run; life would return to normal.", "دروازه‌ها باز می‌شدند؛ کشتی‌ها پهلو می‌گرفتند؛ قطارها راه می‌افتادند؛ زندگی به حالت عادی بازمی‌گشت."),
            StoryParagraph("But Rieux knew that it would not be the same; nothing would ever be the same again.", "اما ریو می‌دانست همان نمی‌شود؛ هیچ چیز هرگز همان نمی‌شد."),
            StoryParagraph("He had lost too much, seen too much, suffered too much.", "بیش از حد از دست داده بود، بیش از حد دیده بود، بیش از حد رنج کشیده بود."),
            StoryParagraph("And yet, he continued to work, because that was all he could do; because work was his way of fighting; because work was his way of living.", "و با این حال، به کار ادامه داد، چون تنها کاری بود که می‌توانست بکند؛ چون کار راهش برای جنگیدن بود؛ چون کار راهش برای زندگی بود."),
            StoryParagraph("One morning, he received a telegram from the sanatorium.", "یک صبح، تلگرامی از آسایشگاه دریافت کرد."),
            StoryParagraph("His wife had died, several days before, alone in her room, without him.", "همسرش چند روز پیش مرده بود، تنها در اتاقش، بدون او."),
            StoryParagraph("He read the telegram, and he folded it, and he put it in his pocket, and he went back to work.", "تلگرام را خواند و تا کرد و در جیبش گذاشت و به کار بازگشت."),
            StoryParagraph("For a long time, he said nothing; he did not speak to anyone about it; he did not weep.", "مدت طولانی چیزی نگفت؛ با کسی درباره‌اش صحبت نکرد؛ گریه نکرد."),
            StoryParagraph("But at night, when he was alone, he thought about her, about their life together, about all the years they had shared.", "اما شب‌ها که تنها بود، به او فکر کرد، به زندگی مشترکشان، به تمام سال‌هایی که با هم گذرانده بودند."),
            StoryParagraph("And he wept, then, at last, in the darkness of his room, in the silence of the empty night.", "و گریست، آن وقت، سرانجام، در تاریکی اتاقش، در سکوت شب خالی."),
            StoryParagraph("The plague had taken everything from him: his wife, his friend, his hope; but it had not taken his will to live, his will to fight, his will to go on.", "طاعون همه چیز را از او گرفته بود: همسرش، دوستش، امیدش؛ اما نخواستنش را نگرفته بود، اراده‌اش به جنگیدن، اراده‌اش به ادامه دادن."),
            StoryParagraph("And so he continued, as everyone continued, in the aftermath of the plague, in the world that remained.", "و اینگونه ادامه داد، همانطور که همه ادامه دادند، در پس‌آیند طاعون، در جهانی که باقی ماند.")
        )
    )

    // ─────────── فصل ۵: پایان طاعون ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The End of the Plague", titlePersian = "پایان طاعون",
        paragraphs = listOf(
            StoryParagraph("The plague finally ended in the spring, after months of suffering, after thousands of deaths.", "طاعون سرانجام در بهار پایان یافت، پس از ماه‌ها رنج، پس از هزاران مرگ."),
            StoryParagraph("The gates of Oran were opened, and the people poured out into the streets, into the squares, into the world.", "دروازه‌های اوران باز شدند و مردم به خیابان‌ها ریختند، به میدان‌ها، به جهان."),
            StoryParagraph("Trains arrived from Paris, from Marseille, from every corner of France.", "قطارها از پاریس رسیدند، از مارسی، از هر گوشه فرانسه."),
            StoryParagraph("Ships docked in the harbor, and their passengers disembarked, and families were reunited.", "کشتی‌ها در بندر پهلو گرفتند و مسافرانشان پیاده شدند و خانواده‌ها به هم رسیدند."),
            StoryParagraph("There were tears, and embraces, and cries of joy; there was laughter, and singing, and dancing.", "اشک بود و آغوش و فریادهای شادی؛ خنده بود و آواز و رقص."),
            StoryParagraph("The people of Oran celebrated for days; they could not believe that it was over; they could not believe that they had survived.", "مردم اوران روزها جشن گرفتند؛ نمی‌توانستند باور کنند تمام شده؛ نمی‌توانستند باور کنند زنده مانده‌اند."),
            StoryParagraph("Rambert was reunited with his wife; she had come from Paris as soon as the gates were opened.", "رامبرت با همسرش به هم رسید؛ به‌محض اینکه دروازه‌ها باز شدند از پاریس آمده بود."),
            StoryParagraph("They held each other for a long time, and they wept, and they laughed, and they could not stop touching each other.", "مدت طولانی هم را در آغوش گرفتند و گریه کردند و خندیدند و نمی‌توانستند از لمس یکدیگر دست بکشند."),
            StoryParagraph("Rieux watched them from a distance, and he was happy for them, but he could not share their joy.", "ریو از دور تماشایشان کرد و برایشان خوشحال بود اما نمی‌توانست شادی‌شان را شریک شود."),
            StoryParagraph("He had lost too much; his wife was dead, his friend was dead, and he was alone.", "بیش از حد از دست داده بود؛ همسرش مرده بود، دوستش مرده بود و او تنها بود."),
            StoryParagraph("He continued to work, as he had always worked; there were still patients, still suffering, still death.", "به کار ادامه داد، همانطور که همیشه کار کرده بود؛ هنوز بیمارانی بودند، هنوز رنج، هنوز مرگ."),
            StoryParagraph("But the plague was over, and the city was returning to life, and Rieux watched it all with a strange detachment.", "اما طاعون تمام شده بود و شهر به زندگی بازمی‌گشت و ریو همه را با جدایی عجیبی تماشا کرد."),
            StoryParagraph("One day, he walked through the streets of Oran, through the same streets he had walked through during the plague.", "یک روز، در خیابان‌های اوران قدم زد، در همان خیابان‌هایی که در طول طاعون در آن‌ها قدم زده بود."),
            StoryParagraph("The cafes were full, the shops were open, the people were laughing.", "کافه‌ها پر بودند، مغازه‌ها باز، مردم می‌خندیدند."),
            StoryParagraph("They had already forgotten; they had already moved on; they had already returned to their ordinary lives.", "از قبل فراموش کرده بودند؛ از قبل رفته بودند؛ از قبل به زندگی‌های معمولی‌شان بازگشته بودند."),
            StoryParagraph("But Rieux had not forgotten; he could not forget; the plague had marked him forever.", "اما ریو فراموش نکرده بود؛ نمی‌توانست فراموش کند؛ طاعون برای همیشه نشانه‌اش گذاشته بود."),
            StoryParagraph("He sat in a cafe, and he ordered a coffee, and he watched the people pass by.", "در کافه‌ای نشست و قهوه‌ای سفارش داد و تماشا کرد که مردم می‌گذرند."),
            StoryParagraph("They were happy, or seemed happy; they were alive, or seemed alive; they were going on, as everyone goes on.", "خوشحال بودند، یا خوشحال به نظر می‌رسیدند؛ زنده بودند، یا زنده به نظر می‌رسیدند؛ ادامه می‌دادند، همانطور که همه ادامه می‌دهند."),
            StoryParagraph("And Rieux thought about the plague, and about everything it had taught him.", "و ریو به طاعون فکر کرد و به هر چیزی که به او آموخته بود."),
            StoryParagraph("It had taught him that life is fragile, that death is always near, that nothing can be taken for granted.", "به او آموخته بود زندگی شکننده است، مرگ همیشه نزدیک، هیچ چیز را نمی‌شود مسلم گرفت."),
            StoryParagraph("It had taught him that human beings are capable of great cruelty, but also of great courage, great kindness, great love.", "به او آموخته بود انسان‌ها قادر به بی‌رحمی بزرگ هستند اما همچنین به شجاعت بزرگ، مهربانی بزرگ، عشق بزرگ."),
            StoryParagraph("It had taught him that the only thing that matters, in the end, is to do one's duty, to help those who suffer, to fight against death.", "به او آموخته بود تنها چیزی که در پایان اهمیت دارد انجام وظیفه است، کمک به رنج‌کشان، جنگیدن با مرگ."),
            StoryParagraph("'The plague,' he wrote in his chronicle, 'is not something that comes and goes; it is always with us, hidden in the depths of every human heart.'", "در تاریخ‌نگاری‌اش نوشت: «طاعون چیزی نیست که بیاید و برود؛ همیشه با ماست، پنهان در اعماق هر قلب انسانی.»"),
            StoryParagraph("'It is the bacillus of indifference, of cruelty, of egoism; and it can always return, in times of crisis, in times of war, in times of fear.'", "«باسیل بی‌تفاوتی است، بی‌رحمی، خودخواهی؛ و همیشه می‌تواند بازگردد، در زمان‌های بحران، در زمان‌های جنگ، در زمان‌های ترس.»"),
            StoryParagraph("'And the only way to fight it,' he continued, 'is with honesty, with work, with compassion; with the simple, daily courage of those who refuse to give up.'", "ادامه داد: «و تنها راه جنگیدن با آن صداقت است، کار، شفقت؛ با شجاعت ساده و روزانه کسانی که از تسلیم شدن امتناع می‌کنند.»"),
            StoryParagraph("'I have seen this courage in many people during the plague,' he wrote, 'and I have seen it in my friend Tarrou, who died fighting the plague.'", "نوشت: «این شجاعت را در بسیاری در طول طاعون دیده‌ام و در دوستم تارو دیده‌ام که در جنگیدن با طاعون مرد.»"),
            StoryParagraph("'I have seen it in Rambert, who chose to stay and help instead of fleeing to his wife.'", "«در رامبرت دیده‌ام که به‌جای فرار نزد همسرش انتخاب کرد بماند و کمک کند.»"),
            StoryParagraph("'I have seen it in my mother, who came to take care of me and never once complained.'", "«در مادرم دیده‌ام که آمد تا از من مراقبت کند و حتی یک بار شکایت نکرد.»"),
            StoryParagraph("'I have seen it in the doctors and nurses who worked until they dropped, and then worked some more.'", "«در دکترها و پرستارانی دیده‌ام که کار کردند تا فرو افتادند و بعد بیشتر کار کردند.»"),
            StoryParagraph("'And I have seen it, most clearly, in the simple people of Oran, who endured the plague with dignity, with patience, with a courage they did not even know they had.'", "«و آن را، واضح‌تر از همه، در مردم ساده اوران دیده‌ام، که طاعون را با وقار تحمل کردند، با صبر، با شجاعتی که حتی نمی‌دانستند دارند.»"),
            StoryParagraph("'The plague,' Rieux concluded, 'is not the enemy of humanity; it is humanity itself, in its darkest form, in its most terrible aspect.'", "ریو نتیجه گرفت: «طاعون دشمن بشریت نیست؛ خودِ بشریت است، در تاریک‌ترین شکلش، در هولناک‌ترین جنبه‌اش.»"),
            StoryParagraph("'And the fight against the plague is the fight to be human, to be kind, to be brave, to be alive.'", "«و مبارزه با طاعون مبارزه برای انسان بودن است، برای مهربان بودن، برای شجاع بودن، برای زنده بودن.»"),
            StoryParagraph("'It is a fight that never ends, a fight that must be fought every day, by every person, in every generation.'", "«مبارزه‌ای است که هرگز تمام نمی‌شود، مبارزه‌ای که باید هر روز جنگید، توسط هر شخص، در هر نسل.»"),
            StoryParagraph("'And I, Bernard Rieux, doctor in Oran, have fought this fight, and I will continue to fight it, as long as I have breath, as long as I have strength.'", "«و من، برنارد ریو، دکتری در اوران، این مبارزه را جنگیده‌ام و به جنگیدنش ادامه می‌دهم، تا وقتی نفس دارم، تا وقتی قوت دارم.»"),
            StoryParagraph("'For the plague will return; it always returns; and we must be ready to fight it again.'", "«زیرا طاعون بازمی‌گردد؛ همیشه بازمی‌گردد؛ و باید آماده باشیم دوباره با آن بجنگیم.»")
        )
    )

    // ─────────── فصل ۶: معنای طاعون ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning of the Plague", titlePersian = "معنای طاعون",
        paragraphs = listOf(
            StoryParagraph("The Plague, published in 1947, is one of the great novels of the twentieth century, and its meaning is as relevant today as it was then.", "طاعون، منتشرشده در ۱۹۴۷، یکی از رمان‌های بزرگ قرن بیستم است و معنایش امروز به همان اندازه آن زمان مرتبط است."),
            StoryParagraph("It is, on the surface, a novel about a plague epidemic in a North African city; but it is, at a deeper level, a philosophical meditation on the human condition.", "در سطح، رمانی است درباره اپیدمی طاعونی در شهری در شمال آفریقا؛ اما در سطح عمیق‌تر، مراقبه‌ای فلسفی درباره وضعیت بشری است."),
            StoryParagraph("The plague is not just a disease; it is a metaphor for everything that threatens human life, human dignity, human meaning.", "طاعون تنها یک بیماری نیست؛ استعاره‌ای است برای هر چیزی که زندگی انسان را تهدید می‌کند، کرامت انسان، معنای انسان."),
            StoryParagraph("It can be war, fascism, injustice, indifference — anything that destroys, anything that kills, anything that makes life meaningless.", "می‌تواند جنگ باشد، فاشیسم، بی‌عدالتی، بی‌تفاوتی — هر چیزی که نابود می‌کند، هر چیزی که می‌کشد، هر چیزی که زندگی را بی‌معنا می‌کند."),
            StoryParagraph("Camus wrote The Plague during the German occupation of France, and many readers saw it as an allegory of the Resistance.", "کامو طاعون را در طول اشغال فرانسه توسط آلمان نوشت و بسیاری از خوانندگان آن را تمثیلی از مقاومت دیدند."),
            StoryParagraph("The plague was the Nazi occupation; the doctors and volunteers were the Resistance; the people of Oran were the French people, suffering under an alien and deadly regime.", "طاعون اشغال نازی بود؛ دکترها و داوطلبان مقاومت؛ مردم اوران مردم فرانسه بودند، رنج‌کش زیر نظامی بیگانه و مرگبار."),
            StoryParagraph("But Camus himself insisted that the novel was more universal than that; it was about the human condition, not just about one historical moment.", "اما خود کامو اصرار داشت رمان از این جهانی‌تر است؛ درباره وضعیت بشری بود، نه تنها درباره یک لحظه تاریخی."),
            StoryParagraph("The central question of the novel is: how should we respond to suffering, to death, to the absurd?", "پرسش محوری رمان این است: چگونه باید به رنج پاسخ دهیم، به مرگ، به پوچی؟"),
            StoryParagraph("Camus offers three possible responses, embodied in three characters: the priest, the journalist, and the doctor.", "کامو سه پاسخ ممکن پیشنهاد می‌دهد، مجسم در سه شخصیت: کشیش، روزنامه‌نگار و دکتر."),
            StoryParagraph("Father Paneloux represents the religious response: the plague is a punishment from God, and we must submit to His will.", "پدر پانلو نماینده پاسخ دینی است: طاعون مجازاتی از جانب خداست و باید تسلیم اراده او شویم."),
            StoryParagraph("But this response breaks down when Paneloux watches an innocent child die; he cannot accept that a just God would allow such a thing.", "اما این پاسخ فرو می‌ریزد وقتی پانلو مرگ کودک بی‌گناهی را تماشا می‌کند؛ نمی‌تواند بپذیرد خدای عادلی چنین چیزی را اجازه دهد."),
            StoryParagraph("Rambert represents the human response: love, personal happiness, the desire to be with those we love.", "رامبرت نماینده پاسخ انسانی است: عشق، خوشبختی شخصی، میل به بودن با کسانی که دوستشان داریم."),
            StoryParagraph("But Rambert realizes that personal happiness is empty if it is bought at the price of others' suffering; he chooses to stay and help.", "اما رامبرت درمی‌یابد خوشبختی شخصی توخالی است اگر به بهای رنج دیگران خریداری شود؛ انتخاب می‌کند بماند و کمک کند."),
            StoryParagraph("Rieux represents the medical response: to fight against death, without hope, without faith, without illusions, simply because it is the right thing to do.", "ریو نماینده پاسخ پزشکی است: جنگیدن با مرگ، بدون امید، بدون ایمان، بدون توهم، تنها چون کار درست است."),
            StoryParagraph("Rieux does not believe in God, does not believe in meaning, does not believe in ultimate victory; but he fights anyway, because that is what a human being must do.", "ریو به خدا باور ندارد، به معنا باور ندارد، به پیروزی نهایی باور ندارد؛ اما به هر حال می‌جنگد، چون این کاری است که یک انسان باید بکند."),
            StoryParagraph("This, for Camus, is the essence of the absurd hero: to live without hope, without illusion, and yet to act, to fight, to create meaning where there is none.", "این، برای کامو، جوهر قهرمان پوچ است: زندگی بدون امید، بدون توهم و با این حال عمل کردن، جنگیدن، آفریدن معنا در جایی که هیچ نیست."),
            StoryParagraph("'The only way to fight the plague,' Rieux says, 'is with decency.'", "ریو می‌گوید: «تنها راه جنگیدن با طاعون، نجابت است.»"),
            StoryParagraph("'And what is decency?' someone asks.", "کسی می‌پرسد: «و نجابت چیست؟»"),
            StoryParagraph("'Doing my job,' Rieux says. 'Simply doing my job.'", "ریو می‌گوید: «انجام کارم. تنها انجام کارم.»"),
            StoryParagraph("This is Camus's answer to the absurd: not heroism, not sainthood, not grand gestures, but the simple, daily, unglamorous performance of one's duty.", "این پاسخ کامو به پوچی است: نه قهرمانی، نه قدیس بودن، نه حرکات بزرگ، بلکه انجام ساده و روزانه و بی‌جذابیت وظیفه."),
            StoryParagraph("The Plague is not a comforting book; it does not offer solutions, it does not promise salvation, it does not pretend that everything will be all right.", "طاعون کتابی دلگرم‌کننده نیست؛ راه‌حل ارائه نمی‌دهد، رستگاری وعده نمی‌دهد، تظاهر نمی‌کند همه چیز خوب می‌شود."),
            StoryParagraph("But it is an honest book, a true book, a book that shows us the world as it is, and asks us what we will do about it.", "اما کتابی صادق است، کتابی راستین، کتابی که جهان را آن‌گونه که هست نشانمان می‌دهد و از ما می‌پرسد در برابرش چه می‌کنیم."),
            StoryParagraph("Camus wrote The Plague as a warning, and as a call to action; he wanted his readers to understand that the plague is always with us, and that we must always be ready to fight it.", "کامو طاعون را همچون هشداری نوشت و همچون فراخوانی به عمل؛ می‌خواست خوانندگانش بفهمند طاعون همیشه با ماست و همیشه باید آماده جنگیدن با آن باشیم."),
            StoryParagraph("The plague is the indifference that allows injustice to flourish; the plague is the egoism that looks away from suffering; the plague is the cowardice that refuses to act.", "طاعون بی‌تفاوتی‌ای است که می‌گذارد بی‌عدالتی شکوفا شود؛ طاعون خودخواهی‌ای است که از رنج روی می‌گرداند؛ طاعون بزدلی‌ای است که از عمل کردن امتناع می‌کند."),
            StoryParagraph("And the fight against the plague is the fight to be human, to be decent, to be kind, to be brave, to be alive.", "و مبارزه با طاعون مبارزه برای انسان بودن است، نجیب بودن، مهربان بودن، شجاع بودن، زنده بودن."),
            StoryParagraph("It is a fight that never ends; it is a fight that must be fought every day, by every person, in every generation.", "مبارزه‌ای است که هرگز تمام نمی‌شود؛ مبارزه‌ای است که باید هر روز جنگید، توسط هر شخص، در هر نسل."),
            StoryParagraph("And it is a fight that, in the end, is worth fighting, even if we cannot win, even if we cannot know what it means, even if we cannot know why we fight.", "و مبارزه‌ای است که در پایان ارزش جنگیدن دارد، حتی اگر نتوانیم ببریم، حتی اگر نتوانیم بدانیم معنایش چیست، حتی اگر نتوانیم بدانیم چرا می‌جنگیم."),
            StoryParagraph("Because the fight itself is what makes us human; because the fight itself is what gives life meaning; because the fight itself is the only thing that matters.", "زیرا خودِ مبارزه همان چیزی است که ما را انسان می‌کند؛ زیرا خودِ مبارزه همان چیزی است که به زندگی معنا می‌دهد؛ زیرا خودِ مبارزه تنها چیزی است که اهمیت دارد."),
            StoryParagraph("The Plague is not a happy book; but it is a hopeful one; not because it promises victory, but because it shows us how to live without it.", "طاعون کتاب شادی نیست؛ اما کتاب امیدبخشی است؛ نه چون پیروزی وعده می‌دهد، بلکه چون نشانمان می‌دهد چگونه بدون آن زندگی کنیم."),
            StoryParagraph("It shows us that we can face the worst that life has to offer, and still remain human, still remain kind, still remain alive.", "نشانمان می‌دهد می‌توانیم با بدترین چیزی که زندگی ارائه می‌دهد روبرو شویم و هنوز انسان بمانیم، هنوز مهربان، هنوز زنده."),
            StoryParagraph("And that, in the end, is enough; that, in the end, is everything.", "و این، در پایان، کافی است؛ این، در پایان، همه چیز است."),
            StoryParagraph("For the plague will return; it always returns; and we must be ready to fight it again.", "زیرا طاعون بازمی‌گردد؛ همیشه بازمی‌گردد؛ و باید آماده باشیم دوباره با آن بجنگیم."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the fight against the plague never ends.", "زیرا مبارزه با طاعون هرگز تمام نمی‌شود."),
            StoryParagraph("It is the fight of every human being, in every time, in every place.", "این مبارزه هر انسانی است، در هر زمان، در هر مکان."),
            StoryParagraph("And it is the only fight worth fighting.", "و تنها مبارزه‌ای است که ارزش جنگیدن دارد.")
        )
    )
}